    }
  }
];

const rows = $input.all();

let text = rows.map((row, index) => {
  return `Row ${index + 1}: ${JSON.stringify(row.json)}`;
}).join('\n');

return [
  {
    json: {
      text: text || 'No readable rows found'
    }
  }
];

const input = $input.first().json;

let raw =
  input.output ??
  input.text ??
  input.message ??
  input.response ??
  input;

if (!raw) {
  throw new Error('No output found from Accounting Agent');
}

// AI may already return an object/array
if (Array.isArray(raw)) {
  raw = JSON.stringify(raw);
} else if (typeof raw === 'object') {
  raw = JSON.stringify(raw);
}

raw = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Find JSON
let jsonText = '';

const arrayMatch = raw.match(/\[[\s\S]*\]/);

if (arrayMatch) {
  jsonText = arrayMatch[0];
} else {
  const objectMatch = raw.match(/\{[\s\S]*\}/);

  if (objectMatch) {
    jsonText = `[${objectMatch[0]}]`;
  }
}

if (!jsonText) {
  throw new Error('No JSON found.\n\nAI returned:\n' + raw);
}

let transactions = JSON.parse(jsonText);

if (!Array.isArray(transactions)) {
  transactions = [transactions];
}

// Safely get user info from Telegram or WhatsApp
let phone = '';
let username = 'User';

try {
  const tg = $('WhatsApp Webhook').first().json;
  const msg = tg.message || tg;
  phone = String(msg.chat?.id || msg.from?.id || '');
  username = msg.from?.first_name || msg.from?.username || 'User';
} catch (e) {}

if (!phone) {
  try {
    const wa = $('Normalize WhatsApp Message Code').first().json;
    phone = String(wa.from || '');
    username = wa.name || 'User';
  } catch (e) {}
}

const validCurrencies = ['INR', 'USD', 'EUR', 'GBP', 'JPY'];

const symbols = {
  INR: '₹',
  USD: '$',
  EUR: '€',
  GBP: '£',
  JPY: '¥'
};

return transactions.map((tx) => {

  let date = String(tx.date || tx.Date || '').trim();

  const today = $now.toFormat('yyyy-MM-dd');
  const currentYear = Number($now.toFormat('yyyy'));

  const yearMatch = date.match(/^(\d{4})-/);
  const year = yearMatch ? Number(yearMatch[1]) : null;

  if (
    !date ||
    date === '2023-10-05' ||
    !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
    (year && year < currentYear - 1)
  ) {
    date = today;
  }

  let currency = String(
    tx.currency ||
    tx.Currency ||
    'INR'
  ).toLowerCase();

  if (!validCurrencies.includes(currency)) {
    currency = 'INR';
  }

  const type = String(
    tx.type ||
    tx.Type ||
    'expense'
  ).toLowerCase();

  const category =
    tx.category ||
    tx.Category ||
    'Other';

  let vendor =
    tx.vendor ||
    tx.Vendor ||
    category ||
    'Not specified';

  const platform =
    tx.platform ||
    tx.Platform ||
    'Direct';

  let product =
    tx.product ||
    tx.Product ||
    category ||
    'Not specified';

  if (
    String(category).toLowerCase() === 'food' &&
    String(product).toLowerCase() === 'food' &&
    String(vendor).toLowerCase() !== 'food'
  ) {
    product = vendor;
  }

  if (
    String(category).toLowerCase() === 'food' &&
    String(vendor).toLowerCase() === 'food' &&
    String(product).toLowerCase() !== 'food'
  ) {
    vendor = product;
  }

  const cleanAmount =
    Number(
      String(tx.amount || tx.Amount || 0)
      .replace(/[^0-9.]/g, '')
    ) || 0;

  const duplicate_key = [
    phone,
    date,
    type,
    String(category).toLowerCase().trim(),
    String(vendor).toLowerCase().trim(),
    cleanAmount
  ].join('|');

  return {
    json: {

      whatsapp_number: phone,
      Username: username,
      Month: date.slice(0, 7),
      Date: date,
      Type: type,
      Category: category,
      Vendor: vendor,
      Platform: platform,
      Product: product,
      Amount: cleanAmount,
      Currency: currency,
      currency_symbol: symbols[currency] || '₹',
      duplicate_key

    }
  };

});

const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json
  }
}));

