parameters.jsCode:
// Normalize transactions from Postgres
const rawRows = $input.all().map(i => i.json);
const rows = rawRows.map(r => ({
  Date: r.transaction_date || r.date || r.Date || '',
  Type: r.type || r.Type || '',
  Category: r.category || r.Category || 'Uncategorized',
  Vendor: r.vendor || r.Vendor || '',
  Amount: Number(r.amount ?? r.Amount ?? 0),
  Currency: r.currency || r.Currency || 'INR'
})).filter(r => r.Date || r.Type || r.Amount > 0);

const question = $("WhatsApp Webhook").first().json.message?.text || $("WhatsApp Webhook").first().json.text || '';
const q = question.toLowerCase();

function amount(v) {
  return Number(String(v || 0).replace(/[^0-9.]/g, '')) || 0;
}

const now = new Date();
let targetYear = '2026';
const yearMatch = q.match(/20\d{2}/);
if (yearMatch) {
  targetYear = yearMatch[0];
}

const monthMap = {
  jan: '01', january: '01',
  feb: '02', february: '02',
  mar: '03', march: '03',
  apr: '04', april: '04',
  may: '05',
  jun: '06', june: '06',
  jul: '07', july: '07',
  aug: '08', august: '08',
  sep: '09', september: '09',
  oct: '10', october: '10',
  nov: '11', november: '11',
  dec: '12', december: '12'
};

let month = `${targetYear}-${String(now.getMonth() + 1).padStart(2, '0')}`;

const hyphenMatch = q.match(/20\d{2}-\d{2}/);
if (hyphenMatch) {
  month = hyphenMatch[0];
} else {
  for (const [mName, mNum] of Object.entries(monthMap)) {
    const regex = new RegExp(`\\b${mName}\\b`, 'i');
    if (regex.test(q)) {
      month = `${targetYear}-${mNum}`;
      break;
    }
  }
}

const monthRows = rows.filter(r => String(r.Date).startsWith(month));

let totalIncome = 0;
let totalExpense = 0;
let categoryTotals = {};

for (const r of monthRows) {
  const type = String(r.Type || '').toLowerCase().trim();
  const amt = amount(r.Amount);
  const cat = String(r.Category || 'Uncategorized').trim();

  if (type === 'income') {
    totalIncome += amt;
  } else {
    totalExpense += amt;
    categoryTotals[cat] = (categoryTotals[cat] || 0) + amt;
  }
}

const sortedCategories = Object.entries(categoryTotals)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([cat, total]) => `  • ${cat}: ₹${total.toLocaleString('en-IN')}`)
  .join('\n');

const savings = totalIncome - totalExpense;
const savingsRate = totalIncome > 0 ? Math.round((savings / totalIncome) * 100) : 0;

const reportText = `📑 *Monthly Financial Report (${month})*\n\n` +
  `💰 Total Income: ₹${totalIncome.toLocaleString('en-IN')}\n` +
  `💸 Total Expense: ₹${totalExpense.toLocaleString('en-IN')}\n` +
  `🎯 Net Savings: ₹${savings.toLocaleString('en-IN')} (${savingsRate}%)\n` +
  `📊 Transactions: ${monthRows.length}\n\n` +
  `🏷️ *Top Spending Categories*:\n${sortedCategories || '  • None'}`;

return [{
  json: {
    month,
    total_income: totalIncome,
    total_expense: totalExpense,
    net_savings: savings,
    savings_rate_percent: savingsRate,
    report: reportText,
    answer: reportText
  }
}];

// Normalize transactions for Subscription Detection
const rawRows = $input.all().map(i => i.json);
const rows = rawRows.map(r => ({
  Date: r.transaction_date || r.date || r.Date || '',
  Type: r.type || r.Type || '',
  Vendor: r.vendor || r.Vendor || r.description || r.Description || '',
  Amount: Number(r.amount ?? r.Amount ?? 0),
  Category: r.category || r.Category || ''
})).filter(r => r.Date || r.Type || r.Amount > 0);

// Group recurring expenses
const recurring = {};
for (const r of rows) {
  const type = String(r.Type || '').toLowerCase();
  if (type === 'income') continue;

  const vendor = String(r.Vendor || '').trim().toLowerCase();
  const amt = Number(r.Amount || 0);
  if (!vendor || amt <= 0) continue;

  const key = `${vendor}_${amt}`;
  if (!recurring[key]) {
    recurring[key] = { vendor: r.Vendor, amount: amt, dates: [], category: r.Category };
  }
  recurring[key].dates.push(r.Date);
}

const detected = Object.values(recurring).filter(item => item.dates.length >= 2);

return detected.map(d => ({
  json: {
    name: d.vendor,
    amount: d.amount,
    frequency: 'monthly',
    category: d.category || 'Subscription',
    status: 'active'
  }
}));

// Normalize transactions and subscriptions for Monthly Calculation
const rawRows = $input.all().map(i => i.json);
const rows = rawRows.map(r => ({
  Date: r.transaction_date || r.date || r.Date || '',
  Type: r.type || r.Type || '',
  Category: r.category || r.Category || 'Uncategorized',
  Amount: Number(r.amount ?? r.Amount ?? 0)
})).filter(r => r.Date || r.Type || r.Amount > 0);

function amount(v) {
  return Number(String(v || 0).replace(/[^0-9.]/g, '')) || 0;
}

const now = new Date();
const lastMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const targetMonth = lastMonthDate.toISOString().slice(0, 7);

const monthRows = rows.filter(r => String(r.Date).startsWith(targetMonth));

let totalIncome = 0;
let totalExpense = 0;
let categoryTotals = {};

for (const r of monthRows) {
  const t = String(r.Type || '').toLowerCase().trim();
  const amt = amount(r.Amount);
  const cat = String(r.Category || 'Uncategorized').trim();

  if (t === 'income') {
    totalIncome += amt;
  } else {
    totalExpense += amt;
    categoryTotals[cat] = (categoryTotals[cat] || 0) + amt;
  }
}

const topCategories = Object.entries(categoryTotals)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([cat, total]) => ({ category: cat, total }));

const savings = totalIncome - totalExpense;

return [{
  json: {
    month: targetMonth,
    total_income: totalIncome,
    total_expense: totalExpense,
    net_savings: savings,
    top_categories: topCategories,
    transaction_count: monthRows.length
  }
}];

const telegram = $("WhatsApp Webhook").first().json.message;
const text = String(telegram.text || '').trim();

function amount(v) {
  return Number(String(v || '').replace(/[^0-9.]/g, '')) || 0;
}

const lower = text.toLowerCase();

let bank = '';
if (lower.includes('hdfc')) bank = 'HDFC';
else if (lower.includes('sbi')) bank = 'SBI';
else if (lower.includes('dbs')) bank = 'DBS';

const money = '(?:₹|rs\\.?|rupees)?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d+)?)';

// Total due / bill amount
const totalDueMatch =
  text.match(new RegExp('(?:credit card bill|card bill|bill|total due|due amount|amount)\\s*' + money, 'i'));

// Due date
const dueDateMatch =
  text.match(/due\s+(?:on\s+)?(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}|\d{1,2}(?:st|nd|rd|th)?\s+[a-zA-Z]+\s+\d{4}|\d{1,2}(?:st|nd|rd|th)?)/i);

// Billing date
const billingDateMatch =
  text.match(/billing date\s*[:\-]?\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}|\d{1,2}(?:st|nd|rd|th)?\s+[a-zA-Z]+\s+\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+[a-zA-Z]+)/i);

// Limit
const limitMatch =
  text.match(new RegExp('limit\\s*' + money, 'i'));

// Current usage
const usageMatch =
  text.match(new RegExp('current usage\\s*[:\\-]?\\s*' + money, 'i'));

// Minimum due
const minimumDueMatch =
  text.match(new RegExp('minimum due\\s*[:\\-]?\\s*' + money, 'i'));

return [{
  json: {
    user_id: String(telegram.chat.id),
    Card_Name: bank ? `${bank} Credit Card` : 'Credit Card',
    Bank: bank || 'Not specified',
    Billing_Date: billingDateMatch ? billingDateMatch[1] : '',
    Due_Date: dueDateMatch ? dueDateMatch[1] : '',
    Limit: limitMatch ? amount(limitMatch[1]) : 0,
    Current_Usage: usageMatch ? amount(usageMatch[1]) : 0,
    Total_Due: totalDueMatch ? amount(totalDueMatch[1]) : 0,
    Minimum_Due: minimumDueMatch ? amount(minimumDueMatch[1]) : 0,
    Status: 'Active'
  }
}];

const telegram = $("WhatsApp Webhook").first().json.message;
const text = String(telegram.text || '').trim();
const lower = text.toLowerCase();

function amount(v) {
  return Number(String(v || '').replace(/[^0-9.]/g, '')) || 0;
}

const money = '(?:₹|rs\\.?|rupees)?\\s*(\\d+(?:,\\d{3})*(?:\\.\\d+)?)';

let bank = '';
if (lower.includes('hdfc')) bank = 'HDFC';
else if (lower.includes('sbi')) bank = 'SBI';
else if (lower.includes('dbs')) bank = 'DBS';
else if (lower.includes('bajaj')) bank = 'Bajaj Finance';

let loanName = 'Loan EMI';
if (lower.includes('home loan')) loanName = 'Home Loan';
else if (lower.includes('personal loan')) loanName = 'Personal Loan';
else if (lower.includes('car loan')) loanName = 'Car Loan';
else if (lower.includes('bike loan')) loanName = 'Bike Loan';
else if (lower.includes('education loan')) loanName = 'Education Loan';

const emiMatch =
  text.match(new RegExp('(?:emi|monthly emi|loan emi)\\s*' + money, 'i')) ||
  text.match(new RegExp(money + '\\s*(?:emi)', 'i'));

const dueDateMatch =
  text.match(/due\s+(?:on\s+)?(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}|\d{1,2}(?:st|nd|rd|th)?\s+[a-zA-Z]+\s+\d{4}|\d{1,2}(?:st|nd|rd|th)?\s+[a-zA-Z]+|\d{1,2}(?:st|nd|rd|th)?)/i);

const interestMatch =
  text.match(/interest(?: rate)?\s*[:\-]?\s*(\d+(?:\.\d+)?)\s*%?/i);

const remainingMatch =
  text.match(new RegExp('(?:remaining balance|balance|remaining)\\s*[:\\-]?\\s*' + money, 'i'));

return [{
  json: {
    user_id: String(telegram.chat.id),
    Loan_Name: loanName,
    Bank: bank || 'Not specified',
    EMI: emiMatch ? amount(emiMatch[1]) : 0,
    Due_Date: dueDateMatch ? dueDateMatch[1] : '',
    Interest_Rate: interestMatch ? interestMatch[1] + '%' : '',
    Remaining_Balance: remainingMatch ? amount(remainingMatch[1]) : 0,
    Status: 'Active',
    Reminder_Type: 'Loan EMI',
    Frequency: 'Monthly'
  }
}];

// Normalize reminders from Postgres
const rawReminders = $input.all().map(i => i.json);
const reminders = rawReminders.map(r => ({
  id: r.id,
  Title: r.title || r.Title || '',
  Amount: Number(r.amount ?? r.Amount ?? 0),
  Due_Date: r.due_date || r.Due_Date || '',
  Last_Notified: r.last_notified || r.Last_Notified || '',
  Status: r.status || r.Status || 'pending',
  whatsapp_number: r.whatsapp_number || ''
}));

const now = new Date();
const todayStr = now.toISOString().slice(0, 10);

const due = reminders.filter(r => {
  if (r.Status === 'completed') return false;
  const dueDateStr = String(r.Due_Date || '').slice(0, 10);
  return dueDateStr <= todayStr;
});

return due.map(d => ({ json: d }));

// Normalize transactions, credit cards, and loans from Postgres
let rawTx = [];
try { rawTx = $('Get Transactions').all().map(i => i.json); } catch(e) {}

const transactions = rawTx.map(r => ({
  Date: r.transaction_date || r.date || r.Date || '',
  Type: r.type || r.Type || '',
  Amount: Number(r.amount ?? r.Amount ?? 0),
  Category: r.category || r.Category || ''
})).filter(r => r.Date || r.Type || r.Amount > 0);

let cards = [];
let loans = [];

try { 
  cards = $('Get Credit Cards').all().map(i => i.json).map(c => ({
    Bank: c.bank || c.Bank || '',
    Total_Due: Number(c.total_due ?? c.Total_Due ?? 0),
    Min_Due: Number(c.min_due ?? c.Min_Due ?? 0)
  })); 
} catch(e) {}

try { 
  loans = $('Get Loans').all().map(i => i.json).map(l => ({
    Loan_Name: l.loan_name || l.Loan_Name || '',
    EMI: Number(l.emi ?? l.EMI ?? 0)
  })); 
} catch(e) {}

const telegramText = $("WhatsApp Webhook").first().json.message?.text || $("WhatsApp Webhook").first().json.text || '';
const question = telegramText.toLowerCase();

function amt(v) {
  return Number(String(v || 0).replace(/[^0-9.]/g, '')) || 0;
}

function getMonths(tx) {
  const m = new Set();
  tx.forEach(t => {
    const d = String(t.Date || '').slice(0, 7);
    if (d.match(/^\d{4}-\d{2}$/)) m.add(d);
  });
  return Array.from(m);
}

const months = getMonths(transactions);
const monthCount = months.length || 1;

let totalIncome = 0;
let totalExpense = 0;

for (const t of transactions) {
  const type = String(t.Type || '').toLowerCase().trim();
  const val = amt(t.Amount);
  if (type === 'income') totalIncome += val;
  else if (type === 'expense') totalExpense += val;
}

const avgIncome = totalIncome / monthCount;
const avgExpense = totalExpense / monthCount;

let totalCCDue = 0;
cards.forEach(c => totalCCDue += amt(c.Total_Due));

let totalEMI = 0;
loans.forEach(l => totalEMI += amt(l.EMI));

const freeCash = avgIncome - avgExpense - totalEMI;

// Extract target purchase amount from question
const numMatch = question.match(/(?:rs\.?|inr|₹)?\s*(\d+(?:,\d+)*(?:\.\d+)?)/i);
const itemAmount = numMatch ? amt(numMatch[1]) : 0;

let affordable = false;
let verdict = '';

if (itemAmount <= 0) {
  verdict = `📈 *Monthly Free Cash Flow*: ₹${Math.round(freeCash).toLocaleString('en-IN')}\n` +
    `💰 Avg Income: ₹${Math.round(avgIncome).toLocaleString('en-IN')}\n` +
    `💸 Avg Expenses: ₹${Math.round(avgExpense).toLocaleString('en-IN')}\n` +
    `🏦 EMIs: ₹${Math.round(totalEMI).toLocaleString('en-IN')}`;
} else if (itemAmount <= freeCash * 0.5) {
  affordable = true;
  verdict = `✅ *Easily Affordable!*\n` +
    `The purchase of ₹${itemAmount.toLocaleString('en-IN')} is well within your monthly free cash flow (₹${Math.round(freeCash).toLocaleString('en-IN')}).`;
} else if (itemAmount <= freeCash) {
  affordable = true;
  verdict = `⚠️ *Affordable, but tight!*\n` +
    `₹${itemAmount.toLocaleString('en-IN')} will consume most of your available free cash (₹${Math.round(freeCash).toLocaleString('en-IN')}).`;
} else {
  affordable = false;
  verdict = `❌ *Not Recommended Right Now!*\n` +
    `₹${itemAmount.toLocaleString('en-IN')} exceeds your monthly free cash flow of ₹${Math.round(freeCash).toLocaleString('en-IN')}.`;
}

return [{
  json: {
    question: telegramText,
    item_amount: itemAmount,
    affordable,
    verdict,
    answer: verdict,
    avg_income: avgIncome,
    avg_expense: avgExpense,
    total_emi: totalEMI,
    total_cc_due: totalCCDue,
    free_cash: freeCash
  }
}];

const input = $input.first().json;
let raw = input.output || input.text || input.content || '';

raw = String(raw)
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const match = raw.match(/\[[\s\S]*\]/);
const jsonString = match ? match[0] : raw;

let transactions = [];
try {
  transactions = JSON.parse(jsonString);
} catch (e) {
  transactions = [];
}

const telegramData = $("WhatsApp Webhook").first().json.message || {};
const whatsappNumber = String(telegramData.chat?.id || telegramData.from?.id || '1104381256');
const username = telegramData.from?.username || telegramData.from?.first_name || 'User';

if (!Array.isArray(transactions) || transactions.length === 0) {
  return [{
    json: {
      status: "NO_TRANSACTIONS",
      message: "No valid transactions extracted from statement"
    }
  }];
}

return transactions.map(tx => {
  const date = String(tx.Date || tx.date || '').trim();
  const month = date.slice(0, 7) || new Date().toISOString().slice(0, 7);

  let type = 'expense';
  const rawType = String(tx.Type || tx.type || 'expense').toLowerCase().trim();
  if (['income', 'credit', 'salary', 'deposit'].some(k => rawType.includes(k))) {
    type = 'income';
  } else if (rawType.includes('transfer')) {
    type = 'transfer';
  } else if (['investment', 'invest', 'gold', 'stocks', 'mutual'].some(k => rawType.includes(k))) {
    type = 'investment';
  } else {
    type = 'expense';
  }

  const category = tx.Category || tx.category || 'Other';
  const vendor = tx.Vendor || tx.vendor || 'N/A';
  const platform = tx.Platform || tx.platform || 'N/A';
  const product = tx.Product || tx.product || 'N/A';
  const amount = Number(tx.Amount ?? tx.amount ?? 0);
  const currency = tx.Currency || tx.currency || 'INR';
  const currencySymbol = tx.currency_symbol || '₹';

  const duplicateKey = `${whatsappNumber}|${date}|${type}|${category.toLowerCase()}|${vendor.toLowerCase()}|${amount}`;

  return {
    json: {
      whatsapp_number: whatsappNumber,
      Username: username,
      Month: month,
      Date: date,
      Type: type,
      type: type,
      Category: category,
      category: category,
      Vendor: vendor,
      vendor: vendor,
      Platform: platform,
      platform: platform,
      Product: product,
      product: product,
      Amount: amount,
      amount: amount,
      Currency: currency,
      currency: currency,
      currency_symbol: currencySymbol,
      duplicate_key: duplicateKey,
      is_duplicate: false
    }
  };
});

const current = $input.all();
return current.map(item => ({
  json: {
    ...item.json,
    is_duplicate: false
  }
}));

// Normalize transactions from Postgres
const rawRows = $input.all().map(i => i.json);
const rows = rawRows.map(r => ({
  Date: r.transaction_date || r.date || r.Date || '',
  Type: r.type || r.Type || '',
  Category: r.category || r.Category || 'Other',
  Vendor: r.vendor || r.Vendor || '',
  Product: r.product || r.Product || '',
  Amount: Number(r.amount ?? r.Amount ?? 0),
  Currency: r.currency || r.Currency || 'INR'
})).filter(r => r.Date || r.Type || r.Amount > 0);

const question = $("WhatsApp Webhook").first().json.message?.text || $("WhatsApp Webhook").first().json.text || '';
const q = question.toLowerCase();

function amount(v) {
  return Number(String(v || 0).replace(/[^0-9.]/g, '')) || 0;
}

const now = new Date();
let targetYear = '2026';
const yearMatch = q.match(/20\d{2}/);
if (yearMatch) targetYear = yearMatch[0];

const monthMap = {
  jan: '01', january: '01', feb: '02', february: '02',
  mar: '03', march: '03', apr: '04', april: '04',
  may: '05', jun: '06', june: '06', jul: '07', july: '07',
  aug: '08', august: '08', sep: '09', september: '09',
  oct: '10', october: '10', nov: '11', november: '11',
  dec: '12', december: '12'
};

let filterMonth = '';
const hyphenMatch = q.match(/20\d{2}-\d{2}/);
if (hyphenMatch) {
  filterMonth = hyphenMatch[0];
} else {
  for (const [mName, mNum] of Object.entries(monthMap)) {
    const regex = new RegExp(`\\b${mName}\\b`, 'i');
    if (regex.test(q)) {
      filterMonth = `${targetYear}-${mNum}`;
      break;
    }
  }
}

if (!filterMonth && !q.includes('all') && !q.includes('total') && !q.includes('across')) {
  filterMonth = `${targetYear}-${String(now.getMonth() + 1).padStart(2, '0')}`;
}

const filteredRows = filterMonth ? rows.filter(r => String(r.Date).startsWith(filterMonth)) : rows;

// Identify category search
const categories = ['food', 'groceries', 'rent', 'travel', 'transport', 'entertainment', 'shopping', 'investment', 'salary', 'loan', 'emi', 'subscription', 'other'];
let detectedCat = '';
for (const c of categories) {
  if (q.includes(c)) {
    detectedCat = c;
    break;
  }
}

let answer = '';

if (detectedCat) {
  let catTotal = 0;
  let catCount = 0;
  filteredRows.forEach(r => {
    const cat = String(r.Category || '').toLowerCase();
    const prod = String(r.Product || '').toLowerCase();
    const vend = String(r.Vendor || '').toLowerCase();
    if (cat.includes(detectedCat) || prod.includes(detectedCat) || vend.includes(detectedCat)) {
      catTotal += amount(r.Amount);
      catCount++;
    }
  });

  const mStr = filterMonth ? ` in ${filterMonth}` : ' across all records';
  answer = `You spent ₹${catTotal.toLocaleString('en-IN')} on ${detectedCat}${mStr} (${catCount} transactions).`;
} else if (q.includes('summary') || q.includes('report') || q.includes('overview')) {
  let inc = 0, exp = 0;
  filteredRows.forEach(r => {
    const t = String(r.Type || '').toLowerCase();
    const a = amount(r.Amount);
    if (t === 'income') inc += a;
    else exp += a;
  });
  const sav = inc - exp;
  const mStr = filterMonth ? ` for ${filterMonth}` : ' (All Time)';
  answer = `📊 *Summary${mStr}*:\n💰 Income: ₹${inc.toLocaleString('en-IN')}\n💸 Expense: ₹${exp.toLocaleString('en-IN')}\n🎯 Savings: ₹${sav.toLocaleString('en-IN')}`;
} else {
  let totalSpent = 0;
  filteredRows.forEach(r => {
    if (String(r.Type || '').toLowerCase() === 'expense') totalSpent += amount(r.Amount);
  });
  const mStr = filterMonth ? ` for ${filterMonth}` : '';
  answer = `Your total expense${mStr} is ₹${totalSpent.toLocaleString('en-IN')}.`;
}

return [{
  json: {
    question,
    filter_month: filterMonth,
    answer
  }
}];

// Normalize transactions, credit cards, and loans for Cashflow Forecast
let rawTx = [];
try { rawTx = $('Get Transactions Forecast').all().map(i => i.json); } catch(e) {}

const transactions = rawTx.map(r => ({
  Date: r.transaction_date || r.date || r.Date || '',
  Type: r.type || r.Type || '',
  Amount: Number(r.amount ?? r.Amount ?? 0)
})).filter(r => r.Date || r.Type || r.Amount > 0);

let cards = [];
let loans = [];

try { 
  cards = $('Get CreditCards Forecast').all().map(i => i.json).map(c => ({
    Bank: c.bank || c.Bank || '',
    Total_Due: Number(c.total_due ?? c.Total_Due ?? 0)
  })); 
} catch(e) {}

try { 
  loans = $('Get Loans Forecast').all().map(i => i.json).map(l => ({
    Loan_Name: l.loan_name || l.Loan_Name || '',
    EMI: Number(l.emi ?? l.EMI ?? 0)
  })); 
} catch(e) {}

function amt(v) {
  return Number(String(v || 0).replace(/[^0-9.]/g, '')) || 0;
}

const now = new Date();
const month = now.toISOString().slice(0, 7);

let income = 0;
let expense = 0;

for (const r of transactions) {
  const d = String(r.Date || '');
  if (d.startsWith(month)) {
    const t = String(r.Type || '').toLowerCase();
    const val = amt(r.Amount);
    if (t === 'income') income += val;
    else if (t === 'expense') expense += val;
  }
}

let ccDue = 0;
cards.forEach(c => ccDue += amt(c.Total_Due));

let loanEmi = 0;
loans.forEach(l => loanEmi += amt(l.EMI));

const projectedSavings = income - expense - ccDue - loanEmi;

const answer = `📊 *Cashflow Forecast for ${month}*:\n` +
  `💰 Current Income: ₹${income.toLocaleString('en-IN')}\n` +
  `💸 Current Expenses: ₹${expense.toLocaleString('en-IN')}\n` +
  `💳 Credit Card Dues: ₹${ccDue.toLocaleString('en-IN')}\n` +
  `🏦 Active Loan EMIs: ₹${loanEmi.toLocaleString('en-IN')}\n` +
  `------------------------\n` +
  `🎯 *Projected Net Savings*: ₹${projectedSavings.toLocaleString('en-IN')}`;

return [{
  json: {
    month,
    current_income: income,
    current_expense: expense,
    credit_card_dues: ccDue,
    loan_emis: loanEmi,
    projected_net_savings: projectedSavings,
    answer
  }
}];

const telegram = $("WhatsApp Webhook").first().json.message;
const text = String(telegram.text || '').trim();

function amount(v) {
  return Number(String(v || '').replace(/[^0-9.]/g, '')) || 0;
}

const lower = text.toLowerCase();

let bank = '';
if (lower.includes('hdfc')) bank = 'HDFC';
else if (lower.includes('sbi')) bank = 'SBI';
else if (lower.includes('dbs')) bank = 'DBS';

const amountMatch =
  text.match(/(?:rs\.?|₹|inr)\s*([0-9,]+(?:\.\d+)?)/i) ||
  text.match(/([0-9,]+(?:\.\d+)?)\s*(?:rs\.?|₹|inr)/i) ||
  text.match(/payment\s+of\s+(?:rs\.?|₹|inr)?\s*([0-9,]+(?:\.\d+)?)/i) ||
  text.match(/bill\s+of\s+([0-9,]+(?:\.\d+)?)/i);

const dateMatch =
  text.match(/on\s+(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/i) ||
  text.match(/on\s+(\d{4}-\d{2}-\d{2})/i);

return [{
  json: {
    user_id: String(telegram.chat.id),
    Bank: bank || 'Not specified',
    Card_Name: bank ? `${bank} Credit Card` : 'Credit Card',
    Payment_Amount: amountMatch ? amount(amountMatch[1]) : 0,
    Payment_Date: dateMatch ? dateMatch[1] : $now.toFormat('yyyy-MM-dd'),
    Type: 'CREDIT_CARD_PAYMENT',
    Status: 'Paid'
  }
}];

const telegram = $("WhatsApp Webhook").first().json.message;
const text = String(telegram.text || '').trim();

function amount(v) {
  return Number(String(v || '').replace(/[^0-9.]/g, '')) || 0;
}

function normalizeDate(value) {
  if (!value) return '';

  const d = String(value).trim();

  // yyyy-mm-dd
  if (/^\d{4}-\d{2}-\d{2}$/.test(d)) return d;

  // dd/mm/yyyy
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)) {
    const [day, month, year] = d.split('/');
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }

  // dd-mm-yyyy
  if (/^\d{1,2}-\d{1,2}-\d{4}$/.test(d)) {
    const [day, month, year] = d.split('-');
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }

  // 7th / 5th / 25th
  const dayMatch = d.match(/(\d{1,2})(st|nd|rd|th)?/i);
  if (dayMatch) {
    const day = dayMatch[1].padStart(2, '0');
    return `${$now.toFormat('yyyy-MM')}-${day}`;
  }

  return '';
}

const lower = text.toLowerCase();

let type = 'Reminder';
if (lower.includes('emi') || lower.includes('loan')) type = 'Loan EMI';
else if (lower.includes('credit card') || lower.includes('card')) type = 'Credit Card';
else if (lower.includes('electricity')) type = 'Bill';
else if (lower.includes('rent')) type = 'Rent';

let name = 'Payment';
if (lower.includes('hdfc')) name = type === 'Credit Card' ? 'HDFC Credit Card' : 'HDFC Bank Loan';
else if (lower.includes('sbi')) name = type === 'Credit Card' ? 'SBI Credit Card' : 'SBI Bank Loan';
else if (lower.includes('dbs')) name = type === 'Credit Card' ? 'DBS Credit Card' : 'DBS Bank Loan';
else if (lower.includes('electricity')) name = 'Electricity Bill';
else if (lower.includes('rent')) name = 'Rent';

// Amount
// Amount
const amountMatch =
  text.match(/emi\s+of\s+([0-9,]+(?:\.\d+)?)/i) ||
  text.match(/of\s+([0-9,]+(?:\.\d+)?)/i) ||
  text.match(/(?:amount|emi|bill|rent|rs\.?|₹|inr)\s*[:\-]?\s*([0-9,]+(?:\.\d+)?)/i);

// Due date
// Due date
const dateMatch =
  text.match(/due\s+(?:on\s+)?(\d{4}-\d{2}-\d{2})/i) ||
  text.match(/due\s+(?:on\s+)?(\d{1,2}\/\d{1,2}\/\d{4})/i) ||
  text.match(/due\s+(?:on\s+)?(\d{1,2}-\d{1,2}-\d{4})/i) ||
  text.match(/on\s+(\d{4}-\d{2}-\d{2})/i) ||
  text.match(/on\s+(\d{1,2}\/\d{1,2}\/\d{4})/i) ||
  text.match(/on\s+(\d{1,2}-\d{1,2}-\d{4})/i) ||
  text.match(/due\s+(?:on\s+)?(\d{1,2}(?:st|nd|rd|th)?)/i);

const rawDate = dateMatch ? dateMatch[1] : '';
const dueDate = normalizeDate(rawDate);

// Frequency
let frequency = 'One-time';
if (lower.includes('monthly') || lower.includes('every month')) frequency = 'Monthly';
else if (lower.includes('weekly') || lower.includes('every week')) frequency = 'Weekly';
else if (lower.includes('daily') || lower.includes('every day')) frequency = 'Daily';
else if (lower.includes('yearly') || lower.includes('annually')) frequency = 'Yearly';

return [{
  json: {
    user_id: String(telegram.chat.id),
    Type: type,
    Name: name,
    Amount: amountMatch ? amount(amountMatch[1]) : 0,
    Due_Date: dueDate,
    Raw_Due_Date: rawDate,
    Frequency: frequency,
    Status: 'Active',
    Reminder_Days_Before: 3,
    Last_Notified_Date: '',
    Created_At: $now.toFormat('yyyy-MM-dd')
  }
}];

const newSubs = $('Subscription Detection Code')
  .all()
  .map(i => i.json)
  .filter(s =>
    s &&
    s.user_id &&
    s.Vendor &&
    s.Amount &&
    s.subscription_key
  );

const existing = $input.all()
  .map(i => i.json)
  .filter(r => r && (r.subscription_key || r.Vendor || r.user_id));

function norm(v) {
  return String(v || '').trim().toLowerCase();
}

if (newSubs.length === 0) {
  return [];
}

const existingKeys = new Set(
  existing
    .map(r =>
      r.subscription_key ||
      `${r.user_id}|${norm(r.Vendor)}|${Math.round(Number(r.Amount || 0))}|monthly`
    )
    .filter(Boolean)
);

return newSubs.map(s => {
  const key =
    s.subscription_key ||
    `${s.user_id}|${norm(s.Vendor)}|${Math.round(Number(s.Amount || 0))}|monthly`;

  return {
    json: {
      ...s,
      subscription_key: key,
      is_duplicate: existingKeys.has(key)
    }
  };
});

const rows = $input.all().map(i => i.json);

const allowedVendors = [
  'netflix',
  'spotify',
  'prime',
  'amazon prime',
  'chatgpt',
  'openai',
  'claude',
  'youtube',
  'google',
  'apple',
  'adobe',
  'canva',
  'hotstar',
  'jio',
  'airtel',
  'internet',
  'mobile recharge'
];

const active = rows.filter(r => {
  const vendor = String(r.Vendor || '').toLowerCase();
  const category = String(r.Category || '').toLowerCase();
  const status = String(r.Status || '').toLowerCase();

  return (
    status === 'active' &&
    r.Vendor &&
    r.Amount &&
    (
      allowedVendors.some(v => vendor.includes(v)) ||
      category.includes('subscription')
    )
  );
});

if (!active.length) {
  return [{
    json: {
      subscription_report:
        '🔁 Subscription List:\nNo active subscriptions found.'
    }
  }];
}

const unique = new Map();

for (const r of active) {
  const key = `${String(r.Vendor).toLowerCase()}|${Math.round(Number(r.Amount || 0))}`;
  if (!unique.has(key)) unique.set(key, r);
}

const lines = [...unique.values()]
  .slice(0, 10)
  .map(r => `• ${r.Vendor} - ₹${Number(r.Amount || 0).toLocaleString('en-IN')}/month`);

return [{
  json: {
    subscription_report: lines.join('\n')
  }
}];

const monthly = $('Monthly Calculation Code').first().json;
const subs = $('Format Subscriptions For Report Code').first().json;

return [{
  json: {
    monthly_report: monthly.report,
    subscription_report: subs.subscription_report
  }
}];

const rows = $input.all().map(i => i.json);

const normalized = $('Normalize WhatsApp Message Code').first().json;
const question = normalized.message_text || '';
const user_id = normalized.from || '';

let previous_context = {};
try {
  const ctx = $('Get Conversation Context').all().map(i => i.json);
  previous_context = ctx[0] || {};
} catch (e) {
  previous_context = {};
}

const q = question.toLowerCase().trim();

const categories = [
  'food','groceries','rent','shopping','transport','bills',
  'health','education','entertainment','subscription','loan',
  'credit card','other'
];

const monthWords = [
  'january','february','march','april','may','june',
  'july','august','september','october','november','december'
];

function detectMonth(text) {
  return monthWords.find(m => text.includes(m)) || previous_context.last_month || '';
}

function detectCategory(text) {
  return categories.find(c => text.includes(c)) || '';
}

function detectTopic(text) {
  if (['categories', 'category', 'breakdown'].includes(text)) return 'categories';
  if (['vendors', 'vendor', 'top vendors'].includes(text)) return 'vendors';
  if (['daily', 'day wise', 'date wise'].includes(text)) return 'daily';

  if (text.includes('today')) return 'today';
  if (text.includes('yesterday')) return 'yesterday';
  if (text.includes('this week')) return 'this_week';
  if (text.includes('last week')) return 'last_week';

  if (text.includes('income') || text.includes('salary') || text.includes('received')) return 'income';
  if (text.includes('subscription')) return 'subscriptions';

  if (text.includes('compare') || text.includes('last month') || text.startsWith('and ')) return 'comparison';

  if (text.includes('biggest') || text.includes('largest') || text.includes('highest') || text.includes('paid the most')) {
    return 'largest_expense';
  }

  const cat = detectCategory(text);
  if (cat) return 'category_detail';

  if (text.includes('spent') || text.includes('spend') || text.includes('expense')) return 'spending_summary';

  // Vendor-only follow-up: e.g. "Zomato", "Amazon", "HDFC"
  if (text.length > 1 && text.length < 40) return 'vendor_detail';

  return previous_context.last_topic || 'general';
}

const current_topic = detectTopic(q);
const current_category = detectCategory(q) || previous_context.last_category || '';
const current_month = detectMonth(q);

let interpreted_question = question;

if (current_topic === 'categories') {
  interpreted_question = `Show category-wise spending breakdown for the latest available month.`;
}

if (current_topic === 'vendors') {
  interpreted_question = `Show top vendors for the latest available month.`;
}

if (current_topic === 'daily') {
  interpreted_question = `Show daily spending breakdown for the latest available month.`;
}

if (current_topic === 'today') {
  interpreted_question = `Show today's income and expenses from FINANCE_CONTEXT.`;
}

if (current_topic === 'yesterday') {
  interpreted_question = `Show yesterday's income and expenses from FINANCE_CONTEXT.`;
}

if (current_topic === 'this_week') {
  interpreted_question = `Show this week's spending summary from FINANCE_CONTEXT.`;
}

if (current_topic === 'last_week') {
  interpreted_question = `Show last week's spending summary from FINANCE_CONTEXT.`;
}

if (current_topic === 'income') {
  interpreted_question = `Show income summary from FINANCE_CONTEXT for the latest available month.`;
}

if (current_topic === 'subscriptions') {
  interpreted_question = `Show subscription-related spending from FINANCE_CONTEXT for the latest available month.`;
}

if (current_topic === 'category_detail' && current_category) {
  interpreted_question = `Show ${current_category} spending details from FINANCE_CONTEXT for the latest available month. Include total, top vendors, and notable transactions.`;
}

if (current_topic === 'vendor_detail') {
  interpreted_question = `Show spending details for vendor "${question}" from FINANCE_CONTEXT. Include total amount, category, dates, and latest available month if relevant.`;
}

if (current_topic === 'comparison') {
  const mentionedCategory = current_category && q.includes(current_category);

  if (mentionedCategory) {
    interpreted_question = `Compare ${current_category} spending between the latest available month and the previous month.`;
  } else {
    interpreted_question = `Compare total spending between the latest available month and the previous month. Include total spent, difference, percentage change, top category changes, and biggest reason for change.`;
  }
}

if (current_topic === 'largest_expense') {
  interpreted_question = `Find the single highest EXPENSE amount from FINANCE_CONTEXT for the latest available month. Show vendor/product, category, amount, and date if available.`;
}

return [{
  json: {
    user_id,
    question: interpreted_question,
    original_question: question,
    current_topic,
    current_category,
    current_month,
    previous_context,
    finance_context: JSON.stringify(rows.slice(-150))
  }
}];

