let rows = [];

try {
  rows = $('Get row(s) in sheet1').all() || [];
} catch (e) {
  rows = [];
}

const current = $input.all();

function cleanAmount(v) {
  return Number(String(v || '').replace(/[^0-9.]/g, '')) || 0;
}

function cleanText(v) {
  return String(v || '').trim().toLowerCase();
}

return current.map(function(item) {
  const data = item.json;

  const categoryRows = rows.filter(function(r) {
    const sameCurrent =
      String(r.json.Date || '') === String(data.Date || '') &&
      cleanText(r.json.Category) === cleanText(data.Category) &&
      cleanAmount(r.json.Amount) === cleanAmount(data.Amount);

    return !sameCurrent &&
      cleanText(r.json.Category) === cleanText(data.Category) &&
      cleanText(r.json.Type) === 'expense';
  });

  const amounts = categoryRows.map(r => cleanAmount(r.json.Amount));

  const avg = amounts.length > 0
    ? amounts.reduce((a, b) => a + b, 0) / amounts.length
    : 0;

  const currentAmount = cleanAmount(data.Amount);
  const isAnomaly =
    cleanText(data.Type) === 'expense' &&
    avg > 0 &&
    currentAmount > avg * 3;

  const anomalyRatio = avg > 0 ? (currentAmount / avg).toFixed(1) : 0;

  return {
    json: {
      ...data,
      average_category_spend: Math.round(avg),
      is_anomaly: isAnomaly,
      anomaly_ratio: anomalyRatio
    }
  };
});

const allItems = $('Budget Check Code').all();

return allItems.map(function(item) {
  const data = item.json;
  const amount = Number(String(data.Amount || 0).replace(/[^0-9.]/g, '')) || 0;
  const category = String(data.Category || '').toLowerCase();
  const type = String(data.Type || '').toUpperCase();

  let suggestion = '✅ Smart Tip: Keep monitoring your spending habits regularly.';

  if (category === 'food') {
