const current = $input.all();
let rows = [];

try {
  rows = $('Get row(s) in sheet1').all() || [];
} catch (e) {
  rows = [];
}

function normalizeText(v) {
  return String(v || '').trim().toLowerCase();
}

function cleanAmount(v) {
  return Number(String(v || '').replace(/[^\d.-]/g, '')) || 0;
}

const budgets = {
  food: 10000,
  shopping: 8000,
  transport: 5000,
  utilities: 7000,
  groceries: 8000,
  bills: 7000,
  entertainment: 4000,
  health: 5000,
  education: 5000,
  'house rent': 15000,
  house_rent: 15000,
  credit_card: 10000,
  'credit card': 10000,
  loan_emi: 15000,
  'loan emi': 15000,
  subscription: 2000,
  investment: 10000,
  salary: 0,
  freelance: 0,
  business: 0,
  cashback: 0,
  refund: 0,
  other: 3000
};

return current.map(function(item) {
  const data = item.json;

  const currentCategory = normalizeText(data.Category);
  const currentType = normalizeText(data.Type);
  const currentAmount = cleanAmount(data.Amount);
  const currentMonth = String(data.Month || data.Date || '').slice(0, 7);
  const budget = budgets[currentCategory] || 0;

  let previousSpend = 0;

  if (currentType === 'expense') {
    for (const row of rows) {
      const r = row.json;

      const sameCurrent =
        String(r.Date || '') === String(data.Date || '') &&
        normalizeText(r.Category) === currentCategory &&
        cleanAmount(r.Amount) === currentAmount;

      const rowMonth = String(r.Month || r.Date || '').slice(0, 7);

      if (
        !sameCurrent &&
        normalizeText(r.Category) === currentCategory &&
        normalizeText(r.Type) === 'expense' &&
        rowMonth === currentMonth
      ) {
        previousSpend += cleanAmount(r.Amount);
      }
    }
  }

  const monthlySpend =
    currentType === 'expense'
      ? previousSpend + currentAmount
      : previousSpend;

  const remainingBudget = budget > 0 ? Math.max(0, budget - monthlySpend) : 0;
  const budgetExceeded = budget > 0 && monthlySpend > budget;
  const exceededBy = budgetExceeded ? monthlySpend - budget : 0;

  let budgetStatus = 'NO_BUDGET_SET';

  if (budget > 0) {
    if (monthlySpend > budget) budgetStatus = 'EXCEEDED';
    else if (monthlySpend >= budget * 0.8) budgetStatus = 'WARNING';
    else budgetStatus = 'SAFE';
  }

  return {
    json: {
      ...data,
      average_category_spend: data.average_category_spend || 0,
      is_anomaly: data.is_anomaly || false,
      anomaly_ratio: data.anomaly_ratio || 0,
      budget,
      monthly_category_spend: monthlySpend,
      remaining_budget: remainingBudget,
      budget_exceeded: budgetExceeded,
      exceeded_by: exceededBy,
      budget_status: budgetStatus
    }
  };
});

const rows = $input.all();

let text = rows.map((row, index) => {
  const r = row.json;

  return `
Row ${index + 1}
Date: ${r.Date || ''}
Description: ${r.Description || r.Item || r.Product || ''}
Amount: ${r.Amount || r.Total || ''}
Type: ${r.Type || ''}
Vendor: ${r.Vendor || ''}
Category: ${r.Category || ''}
`;
}).join('\n');

return [
  {
    json: {
      text: text
    }
  }
];

const rows = $input.all();

let text = rows.map((row, index) => {
  return `Row ${index + 1}: ${JSON.stringify(row.json)}`;
}).join('\n');

return [
  {
    json: {
      text: text || 'No readable rows found'
    }
  }
];

const input = $input.first().json;

let raw =
  input.output ??
  input.text ??
  input.message ??
  input.response ??
  input;

if (!raw) {
  throw new Error('No output found from Accounting Agent');
}

// AI may already return an object/array
if (Array.isArray(raw)) {
  raw = JSON.stringify(raw);
} else if (typeof raw === 'object') {
  raw = JSON.stringify(raw);
}

raw = String(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Find JSON
let jsonText = '';

const arrayMatch = raw.match(/\[[\s\S]*\]/);

if (arrayMatch) {
  jsonText = arrayMatch[0];
} else {
  const objectMatch = raw.match(/\{[\s\S]*\}/);

  if (objectMatch) {
    jsonText = `[${objectMatch[0]}]`;
  }
}

if (!jsonText) {
  throw new Error('No JSON found.\n\nAI returned:\n' + raw);
}

let transactions = JSON.parse(jsonText);

if (!Array.isArray(transactions)) {
  transactions = [transactions];
}

// WhatsApp data
const whatsapp = $('Normalize WhatsApp Message Code').first().json;

const phone = whatsapp.from || '';
const username = whatsapp.name || 'User';

const validCurrencies = ['INR', 'USD', 'EUR', 'GBP', 'JPY'];

const symbols = {
  INR: '₹',
  USD: '$',
  EUR: '€',
  GBP: '£',
  JPY: '¥'
};

return transactions.map((tx) => {

  let date = String(tx.date || tx.Date || '').trim();

  const today = $now.toFormat('yyyy-MM-dd');
  const currentYear = Number($now.toFormat('yyyy'));

  const yearMatch = date.match(/^(\d{4})-/);
  const year = yearMatch ? Number(yearMatch[1]) : null;

  if (
    !date ||
    date === '2023-10-05' ||
    !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
    (year && year < currentYear - 1)
  ) {
    date = today;
  }

  let currency = String(
    tx.currency ||
    tx.Currency ||
    'INR'
  ).toUpperCase();

  if (!validCurrencies.includes(currency)) {
    currency = 'INR';
  }

  const type = String(
    tx.type ||
    tx.Type ||
    'EXPENSE'
  ).toUpperCase();

  const category =
    tx.category ||
    tx.Category ||
    'Other';

  let vendor =
    tx.vendor ||
    tx.Vendor ||
    category ||
    'Not specified';

  const platform =
    tx.platform ||
    tx.Platform ||
    'Direct';

  let product =
    tx.product ||
    tx.Product ||
    category ||
    'Not specified';

  if (
    String(category).toLowerCase() === 'food' &&
    String(product).toLowerCase() === 'food' &&
    String(vendor).toLowerCase() !== 'food'
  ) {
    product = vendor;
  }

  if (
    String(category).toLowerCase() === 'food' &&
    String(vendor).toLowerCase() === 'food' &&
    String(product).toLowerCase() !== 'food'
  ) {
    vendor = product;
  }

  const cleanAmount =
    Number(
      String(tx.amount || tx.Amount || 0)
      .replace(/[^0-9.]/g, '')
    ) || 0;

  const duplicate_key = [
    phone,
    date,
    type,
    String(category).toLowerCase().trim(),
    String(vendor).toLowerCase().trim(),
    cleanAmount
  ].join('|');

  return {
    json: {

      whatsapp_number: phone,
      Username: username,
      Month: date.slice(0, 7),
      Date: date,
      Type: type,
      Category: category,
      Vendor: vendor,
      Platform: platform,
      Product: product,
      Amount: cleanAmount,
      Currency: currency,
      currency_symbol: symbols[currency] || '₹',
      duplicate_key

    }
  };

});

const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json
  }
}));

