const rows = $input.all().map(i => i.json).filter(r => r.Date || r.Type || r.Amount);
const question = $("WhatsApp Webhook").first().json.message.text || '';
const q = question.toLowerCase();

function amount(v) {
  return Number(String(v || 0).replace(/[^0-9.]/g, '')) || 0;
}

const now = new Date();
let month = now.toISOString().slice(0, 7);

// YYYY-MM format
const monthMatch = q.match(/20\d{2}-\d{2}/);
if (monthMatch) {
  month = monthMatch[0];
}

// Month name format
const monthNames = {
  january: '01', jan: '01',
  february: '02', feb: '02',
  march: '03', mar: '03',
  april: '04', apr: '04',
  may: '05',
  june: '06', jun: '06',
  july: '07', jul: '07',
  august: '08', aug: '08',
  september: '09', sep: '09',
  october: '10', oct: '10',
  november: '11', nov: '11',
  december: '12', dec: '12'
};

for (const [name, num] of Object.entries(monthNames)) {
  if (q.includes(name)) {
    month = `${now.getFullYear()}-${num}`;
    break;
  }
}

// last month
if (q.includes('last month')) {
  const d = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  month = d.toISOString().slice(0, 7);
}

// this month
if (q.includes('this month')) {
  month = now.toISOString().slice(0, 7);
}

const monthRows = rows.filter(r => String(r.Month || r.Date || '').slice(0, 7) === month);

let income = 0;
let expense = 0;
const categoryTotals = {};
const vendorTotals = {};

for (const r of monthRows) {
  const type = String(r.Type || '').toUpperCase();
  const amt = amount(r.Amount);
  const cat = r.Category || 'Other';
  const vendor = r.Vendor || 'Other';

  if (type === 'INCOME') income += amt;

  if (type === 'EXPENSE') {
    expense += amt;
    categoryTotals[cat] = (categoryTotals[cat] || 0) + amt;
    vendorTotals[vendor] = (vendorTotals[vendor] || 0) + amt;
  }
}

const savings = income - expense;
const savingsRate = income > 0 ? Math.round((savings / income) * 100) : 0;

const topCategory = Object.entries(categoryTotals).sort((a, b) => b[1] - a[1])[0] || ['None', 0];
const topVendor = Object.entries(vendorTotals).sort((a, b) => b[1] - a[1])[0] || ['None', 0];

let healthScore = 50;
if (savingsRate >= 40) healthScore = 90;
else if (savingsRate >= 25) healthScore = 75;
else if (savingsRate >= 10) healthScore = 60;
else if (savingsRate >= 0) healthScore = 45;
else healthScore = 25;

return [{
  json: {
    month,
    income,
    expense,
    savings,
    savingsRate,
    healthScore,
    topCategory: topCategory[0],
    topCategorySpend: topCategory[1],
    topVendor: topVendor[0],
    topVendorSpend: topVendor[1],
    transactionCount: monthRows.length,
    answer:
`📊 Monthly Finance Report - ${month}

💰 Income: ₹${income.toLocaleString('en-IN')}
💸 Expense: ₹${expense.toLocaleString('en-IN')}
🏦 Savings: ₹${savings.toLocaleString('en-IN')}
📈 Savings Rate: ${savingsRate}%
🧠 Financial Health Score: ${healthScore}/100

📂 Top Category: ${topCategory[0]} - ₹${topCategory[1].toLocaleString('en-IN')}
🏪 Top Vendor: ${topVendor[0]} - ₹${topVendor[1].toLocaleString('en-IN')}

🧾 Transactions: ${monthRows.length}`
  }
}];

const rows = $input.all().map(i => i.json);

function cleanAmount(v) {
  return Number(String(v || 0).replace(/[^\d.-]/g, '')) || 0;
}

function norm(v) {
  return String(v || '').trim().toLowerCase();
}

function addMonth(dateStr) {
  const d = new Date(dateStr);
  if (isNaN(d)) return '';
  d.setMonth(d.getMonth() + 1);
  return d.toISOString().slice(0, 10);
}

const knownSubscriptions = [
  'netflix', 'spotify', 'prime', 'amazon prime',
  'chatgpt', 'openai', 'claude', 'youtube',
  'google', 'apple', 'adobe', 'canva',
  'hotstar', 'jio', 'airtel', 'internet',
  'mobile recharge', 'wifi', 'broadband'
];

const groups = {};

for (const r of rows) {
  const type = String(r.Type || '').trim().toUpperCase();
  if (type !== 'EXPENSE') continue;

  const vendor = r.Vendor || r.Platform || r.Product || '';
  const category = r.Category || 'Other';
  const amount = cleanAmount(r.Amount);
  const date = String(r.Date || '').slice(0, 10);
  const currency = r.Currency || 'INR';
  const user_id = r.user_id || '1104381256';

  if (!vendor || !amount || !date) continue;

  const vendorText = norm(vendor);
  const categoryText = norm(category);
  const productText = norm(r.Product || '');

  const blocked =
    categoryText.includes('food') ||
    categoryText.includes('groceries') ||
    categoryText.includes('shopping') ||
    categoryText.includes('rent') ||
    categoryText.includes('loan') ||
    categoryText.includes('emi') ||
    categoryText.includes('investment') ||
    categoryText.includes('credit card');

  if (blocked) continue;

  const isKnownSubscription =
    knownSubscriptions.some(k =>
      vendorText.includes(k) ||
      categoryText.includes(k) ||
      productText.includes(k)
    ) ||
    categoryText.includes('subscription') ||
    categoryText.includes('utilities') ||
    categoryText.includes('bill');

  if (!isKnownSubscription) continue;

  const key = `${user_id}|${vendorText}|${Math.round(amount)}|monthly`;

  if (!groups[key]) groups[key] = [];

  groups[key].push({
    user_id,
    Vendor: vendor,
    Category: category,
    Amount: amount,
    Date: date,
    Currency: currency
  });
}

const subscriptions = [];

for (const key of Object.keys(groups)) {
  const items = groups[key].sort((a, b) => a.Date.localeCompare(b.Date));

  const first = items[0];
  const last = items[items.length - 1];
  const uniqueMonths = [...new Set(items.map(i => i.Date.slice(0, 7)))];

  if (items.length < 2 && first.Category !== 'Subscription') continue;

  subscriptions.push({
    json: {
      user_id: first.user_id,
      Count: items.length,
      First_Date: first.Date,
      Last_Date: last.Date,
      Vendor: first.Vendor,
      Category: first.Category,
      Frequency: 'Monthly',
      Amount: first.Amount,
      Currency: first.Currency,
      Status: 'Active',
      "Next Expected Date": addMonth(last.Date),
      subscription_key: key
    }
  });
}

return subscriptions;

const rows = $input.all().map(i => i.json);

function cleanAmount(v) {
  return Number(String(v || 0).replace(/[^\d.-]/g, '')) || 0;
}

function norm(v) {
  return String(v || '').trim().toLowerCase();
}

const month = $now.toFormat('yyyy-MM');
const prevMonthDate = $now.minus({ months: 1 });
const prevMonth = prevMonthDate.toFormat('yyyy-MM');

let income = 0;
let expense = 0;
let prevExpense = 0;

const categoryTotals = {};
const vendorTotals = {};
const unusualExpenses = [];

const budgets = {
  food: 10000,
  shopping: 8000,
  transport: 5000,
  utilities: 7000,
  groceries: 8000,
  bills: 7000,
  entertainment: 4000,
  health: 5000,
  education: 5000,
  subscription: 2000,
  other: 3000
};

for (const r of rows) {
  const rowMonth = String(r.Month || r.Date || '').slice(0, 7);
  const type = String(r.Type || '').trim().toUpperCase();
  const amount = cleanAmount(r.Amount);
  const category = r.Category || 'Other';
  const vendor = r.Vendor || 'Unknown';

  if (rowMonth === month && type === 'INCOME') {
    income += amount;
  }

  if (rowMonth === month && type === 'EXPENSE') {
    expense += amount;

    categoryTotals[category] = (categoryTotals[category] || 0) + amount;
    vendorTotals[vendor] = (vendorTotals[vendor] || 0) + amount;

    if (amount > 5000) {
      unusualExpenses.push(`${vendor} - ₹${amount.toLocaleString('en-IN')}`);
    }
  }

  if (rowMonth === prevMonth && type === 'EXPENSE') {
    prevExpense += amount;
  }
}

const savings = income - expense;
const savingsRate = income > 0 ? Math.round((savings / income) * 100) : 0;

const topCategory =
  Object.entries(categoryTotals).sort((a, b) => b[1] - a[1])[0] || ['None', 0];

const topVendor =
  Object.entries(vendorTotals).sort((a, b) => b[1] - a[1])[0] || ['None', 0];

const budgetWarnings = Object.entries(categoryTotals)
  .filter(([cat, amt]) => amt > (budgets[norm(cat)] || Infinity))
  .map(([cat, amt]) => `${cat}: ₹${amt.toLocaleString('en-IN')} spent`);

let healthScore = 50;

if (savingsRate >= 30) healthScore += 25;
else if (savingsRate >= 20) healthScore += 15;
else if (savingsRate >= 10) healthScore += 5;
else healthScore -= 10;

if (expense <= income * 0.7) healthScore += 15;
if (budgetWarnings.length > 0) healthScore -= 10;
if (unusualExpenses.length > 0) healthScore -= 5;

healthScore = Math.max(0, Math.min(100, healthScore));

const spendingTrend = prevExpense > 0
  ? `${expense > prevExpense ? 'Increased' : 'Decreased'} by ₹${Math.abs(expense - prevExpense).toLocaleString('en-IN')} vs last month`
  : 'No previous month data available';

const suggestion =
  savingsRate < 20
    ? 'Try to save at least 20% of your income next month.'
    : 'Good savings performance. Keep tracking consistently.';

const report =
`📊 Monthly Finance Report - ${month}

💰 Income: ₹${income.toLocaleString('en-IN')}
💸 Expense: ₹${expense.toLocaleString('en-IN')}
🏦 Savings: ₹${savings.toLocaleString('en-IN')}
📈 Savings Rate: ${savingsRate}%

🏥 Financial Health Score: ${healthScore}/100

📂 Top Spending Category: ${topCategory[0]} - ₹${topCategory[1].toLocaleString('en-IN')}
🏪 Top Vendor: ${topVendor[0]} - ₹${topVendor[1].toLocaleString('en-IN')}

🔁 Subscription List:
SUBSCRIPTION_REPORT_WILL_BE_INSERTED_BY_AGENT

⚠️ Budget Warnings:
${budgetWarnings.length ? budgetWarnings.map(w => '• ' + w).join('\n') : 'No budget warnings.'}

📊 Spending Trend:
${spendingTrend}

🚨 Unusual Expenses:
${unusualExpenses.length ? unusualExpenses.map(e => '• ' + e).join('\n') : 'No unusual expenses detected.'}

💡 Suggestion:
${suggestion}`;

return [{
  json: {
    Month: month,
    Income: income,
    Expense: expense,
    Savings: savings,
    "Savings Rate": savingsRate + '%',
    "Health Score": healthScore,
    "Top Category": topCategory[0],
    "Top Vendor": topVendor[0],
    Subscriptions: "Use SUBSCRIPTION_REPORT only",
    "Budget Warnings": budgetWarnings.join(', ') || 'None',
    "Spending Trend": spendingTrend,
    "Unusual Expenses": unusualExpenses.join(', ') || 'None',
    Suggestion: suggestion,
    report
  }
}];

