function parseDate(value) {
  if (!value) return null;

  const d = String(value).trim();

  if (/^\d{4}-\d{2}-\d{2}$/.test(d)) {
    const [y, m, day] = d.split('-').map(Number);
    return new Date(y, m - 1, day);
  }

  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)) {
    const [day, m, y] = d.split('/').map(Number);
    return new Date(y, m - 1, day);
  }

  if (/^\d{1,2}-\d{1,2}-\d{4}$/.test(d)) {
    const [day, m, y] = d.split('-').map(Number);
    return new Date(y, m - 1, day);
  }

  return null;
}

function startOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function diffDays(due, now) {
  const oneDay = 1000 * 60 * 60 * 24;
  return Math.ceil((startOfDay(due) - startOfDay(now)) / oneDay);
}

function addFrequency(date, frequency) {
  const d = new Date(date);
  const f = String(frequency || '').toLowerCase();

  if (f === 'daily') d.setDate(d.getDate() + 1);
  else if (f === 'weekly') d.setDate(d.getDate() + 7);
  else if (f === 'monthly') d.setMonth(d.getMonth() + 1);
  else if (f === 'yearly') d.setFullYear(d.getFullYear() + 1);

  return d;
}

function fmt(date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

const alerts = [];
const todayText = $now.toFormat('yyyy-MM-dd');

for (const r of rows) {
  const status = String(r.Status || '').toLowerCase().trim();
  if (status !== 'active') continue;

  const userId = String(r['user id'] || r.user_id || '').trim();
  if (!userId) continue;

  let due = parseDate(r['Due Date'] || r.Due_Date);
  if (!due) continue;

  const frequency = r.Frequency || 'One-time';

  while (startOfDay(due) < startOfDay(today)) {
    if (String(frequency).toLowerCase() === 'one-time') break;
    due = addFrequency(due, frequency);
  }

  const daysLeft = diffDays(due, today);

  if (
    String(frequency).toLowerCase() === 'one-time' &&
    daysLeft < 0
  ) {
    continue;
  }

  const reminderDays = Number(r['Reminder Days Before'] || r.Reminder_Days_Before || 3);
  const lastNotified = String(r['Last Notified Date'] || r.Last_Notified_Date || '').trim();

  if (
    daysLeft >= 0 &&
    daysLeft <= reminderDays &&
    lastNotified !== todayText
  ) {
    alerts.push({
      json: {
        row_number: r.row_number,
        user_id: userId,
        Type: r.Type || 'Reminder',
        Name: r.Name || 'Payment',
        Amount: cleanAmount(r.Amount),
        Due_Date: fmt(due),
        Frequency: frequency,
        Status: status,
        Reminder_Days_Before: reminderDays,
        Last_Notified_Date: todayText,
        Created_At: r['Created At'] || r.Created_At || '',
        days_left: daysLeft,
