function getMonthRange(mode) {
  const now = new Date();

  if (mode === 'last_month') {
    const d = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    return d.toISOString().slice(0, 7);
  }

  return now.toISOString().slice(0, 7);
}

let rangeMode = 'this_month';

if (question.includes('last month')) {
  rangeMode = 'last_month';
}

if (
  question.includes('all time') ||
  question.includes('overall') ||
  question.includes('total history') ||
  question.includes('lifetime')
) {
  rangeMode = 'all_time';
}

let targetMonth = getMonthRange(rangeMode);

// Specific month like 2026-04
const specificMonthMatch = question.match(/20\d{2}-\d{2}/);
if (specificMonthMatch) {
  rangeMode = 'specific_month';
  targetMonth = specificMonthMatch[0];
}

// Extract purchase amount
const purchaseMatch =
  telegramText.match(/(?:worth|cost|price|buy|purchase|for)\s*(?:₹|rs\.?|rupees)?\s*([0-9,]+(?:\.\d+)?)/i) ||
  telegramText.match(/(?:₹|rs\.?|rupees)\s*([0-9,]+(?:\.\d+)?)/i) ||
  telegramText.match(/([0-9,]+(?:\.\d+)?)/);

